export const VERSION = 1;
export function initialState(){return {version:VERSION,power:false,screen:'off',usb:false,ethernet:false,bootDevice:'disk',biosVisited:false,ventoyBooted:false,installed:false,adminSet:false,roles:[],domain:'',promoted:false,restarted:false,functionalLevel:'Windows Server 2012 R2',ous:[],users:[],folders:[],securityVisited:false,network:{dhcp:true,ip:'192.168.1.10',mask:'255.255.255.0',gateway:'192.168.1.1',dns:'127.0.0.1'},computerName:'WIN-SERVER',events:[],startedAt:Date.now()};}
export const phases = [
 {title:'Connect & boot',subtitle:'Get your server ready',items:[['usb','Insert the Ventoy USB drive'],['ethernet','Connect the Ethernet cable'],['bios','Enter BIOS setup'],['ventoy','Boot from Ventoy']]},
 {title:'Install Windows Server',subtitle:'Build your operating system',items:[['installed','Install Windows Server 2012 R2'],['admin','Set the Administrator password']]},
 {title:'Create your domain',subtitle:'Configure Active Directory',items:[['role','Add the AD DS server role'],['domain','Promote: add a new forest'],['restart','Restart the domain controller']]},
 {title:'Organize & add users',subtitle:'Give your domain a structure',items:[['ou','Create an unprotected organizational unit'],['user','Create a user in that OU'],['password','Configure the user password options']]},
 {title:'Create a shared folder',subtitle:'Prepare for folder redirection',items:[['folder','Create a folder'],['share','Enable advanced sharing'],['full','Allow Full Control in share permissions'],['security','Open the folder Security tab']]}
];
export function checks(s){const ou=s.ous.find(o=>!o.protected);const user=s.users.find(u=>s.ous.some(o=>o.id===u.ou&&!o.protected));const shares=s.folders.filter(f=>f.shared);return {usb:s.usb,ethernet:s.ethernet,bios:s.biosVisited,ventoy:s.ventoyBooted,installed:s.installed,admin:s.adminSet,role:s.roles.includes('AD DS'),domain:s.promoted,restart:s.restarted,ou:!!ou,user:!!user,password:s.users.some(u=>s.ous.some(o=>o.id===u.ou&&!o.protected)&&!u.mustChange&&u.neverExpires),folder:s.folders.length>0,share:shares.length>0,full:shares.some(f=>f.fullControl),security:shares.some(f=>f.fullControl&&f.securityVisited)};}
export function progress(s){const c=checks(s); const total=phases.reduce((n,p)=>n+p.items.length,0); const done=Object.values(c).filter(Boolean).length;return {done,total,percent:Math.round(done/total*100),phase:Math.max(0,phases.findIndex(p=>p.items.some(([key])=>!c[key])))};}
export function validDomain(value){return /^(?=.{3,253}$)([a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}$/.test(value);}
export function validPassword(value){return value.length>=8 && [/[A-Z]/,/[a-z]/,/\d/,/[^A-Za-z0-9]/].filter(r=>r.test(value)).length>=3;}
export function validIP(value){return /^(\d{1,3}\.){3}\d{1,3}$/.test(value)&&value.split('.').every(v=>Number(v)>=0&&Number(v)<=255);}
export function cleanState(raw){const fresh=initialState();if(!raw||raw.version!==VERSION)return fresh; const s={...fresh,...raw}; s.network={...fresh.network,...raw.network};for(const k of ['roles','ous','users','folders','events'])if(!Array.isArray(s[k]))s[k]=[]; if(['installing','restarting','post'].includes(s.screen))s.screen=s.adminSet?'desktop':s.installed?'password':'off';if(raw.screen==='restarting'&&s.adminSet&&s.promoted)s.restarted=true;s.power=s.screen!=='off';return s;}
